from gtlib import *
SRC=lambda t:[('Temple facts:',f'Wikipedia, “{t}”, and temple, tourism and district information, as summarised in our earlier guide.')]
W=[('🛕','Garbhagṛha','The sanctum, the “womb-house” of the image.'),('🪨','Monolith','An image carved from a single stone.'),('🌀','Valampuri','A right-turned trunk, rare and especially revered.'),('🍯','Prasāda','Food offered to the god and shared as blessing.'),('🙏','Sevā','A ritual service offered by a devotee.'),('💧','Tīrtha','A sacred tank or pond.')]
def coast(label,extra=''): return svg(560,170,label,f'<rect width="560" height="170" fill="#dfe9f6"/><path d="M0 120 q140 -12 280 0 t280 0 v50 h-560z" fill="#5a8ab8"/>'+g(130,120,1,tree('#2f7a3a'))+g(300,115,1,palace())+extra)
def rock(label,extra=''): return svg(560,170,label,f'<rect width="560" height="170" fill="#fde9c8"/><path d="M140 160 q40 -150 140 -140 q100 10 140 140z" fill="#9a8a6a"/>'+g(280,40,.6,palace())+extra)
def stand(label,note=''): return svg(560,170,label,f'<rect width="560" height="170" fill="#fff3cf"/>'+g(280,165,1.6,ganesha(c='#6a6a72',seat=False,arms=2))+g(150,160,1.1,lamp())+g(410,160,1.1,lamp())+(lab(280,18,note,12) if note else ''))
# ---------- GOKARṆA ----------
temple(9,dict(kicker='GAṆEŚA TEMPLES · KARNATAKA COAST · THE BOY AND THE LIṄGA',
cov=covart('A boy holding a liṅga on a beach, a demon king hurrying back, a temple town behind',g(120,180,1,child())+g(150,150,.6,linga())+g(330,180,1.2,demon('#5a3a6a'))+g(230,170,.8,palace())),
cap='The boy who saved the liṅga',how='How the boy Gaṇeśa <b>set down the ātmaliṅga</b>, the standing granite image with <b>Rāvaṇa’s mark</b>, the temple town, the <b>Śivarātri chariot</b>, and the coast of five shrines.',
desc='Gokarṇa’s Mahāgaṇapati explained: the boy Gaṇeśa who set down Śiva’s ātmaliṅga before Rāvaṇa, the standing granite image with the mark of the blow, the temple town and Mahābaleśvara, the Śivarātri chariot, and the coastal pilgrimage.',
fw=['On the coast of Uttara Kannada, in the temple town of <b>Gokarṇa</b>, stands a small boy in granite: <b>Mahāgaṇapati</b>, the Gaṇeśa who, in the story, outwitted Rāvaṇa and kept Śiva’s ātmaliṅga in India.','Pilgrims greet him before they go to Mahābaleśvara, the liṅga he saved. This guide covers the legend, the image, the town, the chariot festival and the coast. The full story is in our '+L('/ganesha/stories/gokarna/','Stories guide')+'.'],fwtk=[('z','Gaṇeśa tricked Rāvaṇa?'),('b','As a cowherd boy, Zappy. With perfect timing.')],
glance=[('Where','Gokarṇa, Kumta taluka, Uttara Kannada, Karnataka'),('Shrine','Mahāgaṇapati, near the Mahābaleśvara temple'),('Image','Granite, standing, two-armed, about 5 ft'),('Mark','A hollow on the head: Rāvaṇa’s blow, says tradition'),('Custom','Worshipped before Mahābaleśvara'),('Chariot','Śivarātri ratha starts from the Gaṇapati temple'),('Town','Praised by Kālidāsa; a Tēvāram shrine'),('Coast','Iḍagunji 68 km; Muruḍeśvara nearby')],
where=['<b>On the coast.</b> Gokarṇa lies between the Arabian Sea and the Western Ghāṭs in Kumta taluka, Uttara Kannada.','<b>Two temples.</b> Mahāgaṇapati stands a short walk from the Mahābaleśvara temple, at the end of Car Street.','<b>The name.</b> “Cow’s ear”: tradition explains it by the shape of the land or by a story of Śiva emerging from the ear of the earth-cow. (Tradition.)'],wtk=[('z','A town called cow’s ear?'),('b','Gokarṇa, Zappy. The stories explain it two ways.')],wk='By the <b>sea</b>.',
lt='THE BOY AND THE LIṄGA',ls='Rāvaṇa outwitted',strip=strip('Three panels: Rāvaṇa carrying a liṅga; a cowherd boy holding it at dusk; the liṅga fixed in the ground and Rāvaṇa striking the boy',[panel([(demon('#5a3a6a'),.9),(linga(),.5)],'#e9e3f5',150),panel([(child(),.8),(linga(),.5),(moon(),.5)],'#20243a',150),panel([(linga(),.8),(demon('#5a3a6a'),.8)],'#fde4e4',150)],['the gift from Kailāsa','the boy at dusk','set down for ever']),lsrc='Temple tradition and the Purāṇic Gokarṇa story; tellings differ.',
lsteps=['<b>Rāvaṇa</b> won Śiva’s own ātmaliṅga, on one condition: wherever it touched the ground, there it would stay.','The gods feared Lanka would become invincible. Viṣṇu hid the sun, making false dusk, and Rāvaṇa had to stop for his evening rites.','A cowherd boy, <b>Gaṇeśa</b>, offered to hold the liṅga, but said he would call three times and then set it down.','Rāvaṇa came back too late. The liṅga was on the ground; with all his strength he could not lift it. So it is <b>Mahābala</b>, “of great strength”.','In anger Rāvaṇa struck the boy’s head. The hollow on the image is said to be that blow.'],ltk=[('z','Gaṇeśa took a blow for it?'),('b','And kept smiling, Zappy. The liṅga stayed.')],lk='The liṅga <b>stays</b>.',
more=[('image','THE IMAGE','A boy who stands',stand('A standing two-armed granite Gaṇeśa, a hollow on the head','standing · two-armed · granite'),['<b>Form.</b> Granite, standing, two-armed, about five feet tall, with a boy’s proportions: a short-legged cowherd Gaṇeśa, a form found along this coast.','<b>The hollow.</b> A hollow on top of the head is pointed out as the mark of Rāvaṇa’s blow.','<b>Mood.</b> Calm and unruffled: the clever boy who won without fighting.'],[('z','A Gaṇeśa standing up?'),('b','Along this coast, often, Zappy. Iḍagunji’s stands too.')],'The standing <b>boy</b>.'),
('mahabala','MAHĀBALEŚVARA','The liṅga he saved',svg(560,170,'A liṅga seen through an opening in a stone base',f'<rect width="560" height="170" fill="#e3eaf3"/>'+g(280,150,1.6,linga())+g(450,150,1,lamp())),['<b>The ātmaliṅga.</b> In the Mahābaleśvara temple the liṅga is seen through an opening in its base, said to be the place where it sank into the earth.','<b>First Gaṇeśa.</b> By custom pilgrims greet Mahāgaṇapati first, then Mahābaleśvara: thanks to the boy before the liṅga.','<b>Old fame.</b> Kālidāsa mentions the lord of Gokarṇa, and the Tamil Tēvāram hymns praise him.'],[('z','First the boy, then the liṅga?'),('b','Thanks first, Zappy.')],'Thanks <b>first</b>.'),
('chariot','THE ŚIVARĀTRI CHARIOT','Car Street’s great day',svg(560,170,'A huge temple chariot pulled along a street by crowds',f'<rect width="560" height="170" fill="#fde9c8"/>'+g(300,150,1.6,palace())+''.join(g(x,155,.45,person('#c0392b')) for x in range(60,220,20))),['<b>The festival.</b> At Mahāśivarātri the great chariot of Mahābaleśvara is drawn along Car Street.','<b>From Gaṇeśa’s door.</b> The procession starts from the Gaṇapati temple at the end of the street.','<b>Read more.</b> Our '+L('/festivals/maha-shivaratri/','Mahāśivarātri')+' guide.'],[('z','The chariot starts at Gaṇeśa’s temple?'),('b','Where else, Zappy?')],'The chariot starts <b>with Gaṇeśa</b>.'),
('rites','A TOWN OF RITES','Pilgrims and ancestors',coast('A temple town by the sea with pilgrims at the shore',''.join(g(x,140,.45,person('#1d4f8a')) for x in (380,410,440))),['<b>Ancestor rites.</b> Many Karnataka families come to Gokarṇa to perform death and ancestor rites; read our '+L('/festivals/pitru-paksha/places/','Pitṛ Pakṣa places')+' guide.','<b>The beach.</b> Pilgrims bathe in the sea before going to the temples.','<b>Today.</b> Gokarṇa is also famous for its beaches; the temple town keeps its old rhythm beside them.'],[('z','Temples and beaches?'),('b','Both, Zappy. Bathe, then pray.')],'Sea, <b>then shrine</b>.'),
('coastal','THE COAST OF FIVE SHRINES','Fragments of the liṅga',coast('A coastline with five small shrines along it',''.join(g(x,110,.35,palace()) for x in (80,180,380,460,520))),['<b>Pañca-kṣetras.</b> Tradition links five coastal shrines with fragments of the liṅga that Rāvaṇa tore at in his rage: Gokarṇa, Muruḍeśvara and others.','<b>Gaṇeśa on the coast.</b> '+L('/ganesha/temples/idagunji/','Iḍagunji')+', about 68 km south, makes a natural next stop.','<b>Season.</b> October to March is the most comfortable.'],[('z','Five pieces of one liṅga?'),('b','So the coast tells it, Zappy.')],'One story, <b>five shrines</b>.'),
('meaning','THE CLEVER BOY','What Gokarṇa teaches',stand('A smiling boy Gaṇeśa','calm, clever, kind'),['<b>Wit, not force.</b> Gaṇeśa wins by timing, not strength. Many read the story as wisdom outwitting power. (Interpretation.)','<b>Fair warning.</b> He called three times before setting the liṅga down: clever, but honest.','<b>The blow.</b> He takes Rāvaṇa’s anger calmly. The mark on his head is worn like a badge.'],[('z','So brains beat muscles?'),('b','At Gokarṇa they did, Zappy.')],'Wit <b>over force</b>.')],
words=W,gtk=[('z','Garbhagṛha again!'),('b','You’ll use it at every temple, Zappy.')],
end=['<b>Where.</b> Gokarṇa, Uttara Kannada coast.','<b>Legend.</b> The boy Gaṇeśa set down the ātmaliṅga.','<b>Image.</b> Standing granite boy, with Rāvaṇa’s mark.','<b>Custom.</b> Gaṇeśa first, then Mahābaleśvara.','<b>Festival.</b> Śivarātri chariot from Gaṇeśa’s door.'],endnext='Next: '+L('/ganesha/temples/idagunji/','Iḍagunji')+', down the coast.',
src=SRC('Gokarna, Karnataka'),unver='the origin of the name; the five-shrine tradition; the hollow as Rāvaṇa’s blow (tradition).',study='Study notes on Gokarṇa’s Mahāgaṇapati.'))
# ---------- IḌAGUNJI ----------
temple(10,dict(kicker='GAṆEŚA TEMPLES · KARNATAKA COAST · THE KALI-AGE GAṆEŚA',
cov=covart('A standing two-armed Gaṇeśa with a modaka and a lotus bud by a river',g(220,190,1.3,ganesha(c='#6a6a72',seat=False,arms=2))+g(90,190,1,tree('#2f7a3a'))+'<path d="M300 200 q70 -10 140 0 v20 h-140z" fill="#8fb8de"/>'+g(370,170,.8,sage())),
cap='Standing for the Kali age',how='The <b>sages</b> at the end of an age, the standing <b>two-armed</b> image with both tusks, the tanks, <b>Nārada</b>, and the coastal circuit.',
desc='Iḍagunji’s Gaṇeśa explained: the sages’ rites at the end of the Dvāpara age and Nārada’s advice, the standing two-armed image with modaka and lotus, the temple and its tanks, festivals, and the coastal pilgrimage with Gokarṇa and Muruḍeśvara.',
fw=['Near the Śarāvatī river in Honnāvar taluka stands one of Karnataka’s best-loved Gaṇeśas: a <b>standing, two-armed</b> image at <b>Iḍagunji</b>, drawing about a million pilgrims a year.','Its legend is set at the very end of the Dvāpara age, as sages prepared for the hard Kali age to come. This guide covers the legend, the image, the temple, Nārada, the festivals and the coast.'],fwtk=[('z','Gaṇeśa came for the Kali age?'),('b','So the sages could begin it with his protection, Zappy.')],
glance=[('Where','Iḍagunji, Honnāvar taluka, Uttara Kannada'),('River','Near the Śarāvatī'),('Image','Standing, two-armed: modaka and lotus bud'),('Tusks','Both intact, many say'),('Age','Tradition: about 1,500 years'),('Pilgrims','Around a million a year'),('Tanks','Cakra-, Brahma-, Gaṇeśa- and Deva-tīrtha'),('Near','Muruḍeśvara 16 km; Gokarṇa 68 km')],
where=['<b>Honnāvar.</b> Iḍagunji lies inland from the coast in Honnāvar taluka, near the Śarāvatī river.','<b>The river.</b> Upstream the Śarāvatī falls at Jog; downstream it meets the sea at Honnāvar.','<b>Railway.</b> The nearest station is Manki, on the Konkan line.'],wtk=[('z','Jog Falls on the same river?'),('b','The Śarāvatī, Zappy. Falls upstream, Gaṇeśa downstream.')],wk='By the <b>Śarāvatī</b>.',
lt='THE SAGES AT THE END OF AN AGE',ls='Nārada’s advice',strip=strip('Three panels: sages at a failing fire rite; Nārada pointing to a spot; Gaṇeśa appearing with the gods',[panel([(sage(),.8),(fire(),.6)],'#fde4e4',150),panel([(sage('#fff'),.9)],'#e3f5e9',150),panel([(ganesha(seat=False,arms=2),.6),(god(),.6)],'#fff3cf',150)],['rites that fail','Nārada’s counsel','Gaṇeśa comes']),lsrc='Temple tradition.',
lsteps=['At the end of the Dvāpara age, as Kṛṣṇa prepared to leave the earth, sages feared the coming <b>Kali age</b>.','Led by <b>Vālakhilya</b>, they began rites in the forest of Kuñjavana by the Śarāvatī. Obstacles kept wrecking them.','The sage <b>Nārada</b> told them to worship Vighneśvara first, chose the site and, with the sages, dug a new tank, Deva-tīrtha.','Nārada brought Gaṇeśa and the gods. The rites succeeded.','The sages built a temple where Gaṇeśa had appeared, so that the Kali age would begin under his care.'],ltk=[('z','Nārada again!'),('b','The sage who always knows whom to call, Zappy.')],lk='Kali begins <b>under Gaṇeśa</b>.',
more=[('image','THE IMAGE','Standing, two-armed',stand('A standing two-armed Gaṇeśa holding a modaka and a lotus bud','modaka · lotus bud'),['<b>Form.</b> Standing on a stone slab, two-armed, holding a <b>modaka</b> and a <b>lotus bud</b>.','<b>Tusks.</b> Visitors often note both tusks intact and no serpent at the waist. Some devotees read this as a Gaṇeśa from before he broke his tusk to write the Mahābhārata; a devotional reading, not a date.','<b>Coast style.</b> Like other old standing Gaṇeśas of this coast, including Gokarṇa’s.'],[('z','Both tusks?'),('b','So devotees point out, Zappy.')],'Modaka and <b>lotus</b>.'),
('temple','THE TEMPLE AND ITS TANKS','Water from the legend',svg(560,170,'A medium temple with several tanks around it',f'<rect width="560" height="170" fill="#e3f5e9"/>'+g(280,140,1,palace())+''.join(f'<rect x="{x}" y="140" width="70" height="18" fill="#8fb8de"/>' for x in (40,140,350,450))),['<b>Medium-sized.</b> A modest shrine by Karnataka standards, always busy.','<b>Tanks.</b> Cakra-tīrtha, Brahma-tīrtha, Gaṇeśa-tīrtha and Deva-tīrtha recall the sages’ story.','<b>Nārada.</b> A figure of Nārada stands near the deity: the sage who brought him.'],[('z','So many tanks!'),('b','Each with its piece of the story, Zappy.')],'Tanks <b>of the legend</b>.'),
('offerings','OFFERINGS AND DAYS','How Iḍagunji worships',svg(560,170,'A plate of modakas, dūrvā and a lamp before a standing Gaṇeśa',f'<rect width="560" height="170" fill="#fff3cf"/>'+g(160,150,1.4,plate())+g(160,120,.8,modaka())+g(300,150,1,durva())+g(430,160,1,ganesha(seat=False,arms=2))),['<b>Busy days.</b> Saṅkrānti, Gaṇeśa Caturthī, Vijayādaśamī and Dīpāvali, and Saṅkaṣṭī each month.','<b>Offerings.</b> Modakas, coconuts and dūrvā grass; many families come to begin new ventures with his blessing.','<b>Arrangements.</b> Timings and sevās are set by the temple; check locally.'],[('z','People start businesses here?'),('b','And journeys and schooling, Zappy. Beginnings start with Gaṇeśa.')],'<b>Beginnings</b> blessed.'),
('coast','THE COASTAL CIRCUIT','Gokarṇa, Iḍagunji, Muruḍeśvara',coast('A coastline with three temples marked'),['<b>A circuit.</b> Pilgrims often combine '+L('/ganesha/temples/gokarna/','Gokarṇa')+', Iḍagunji and Muruḍeśvara.','<b>Distances.</b> Muruḍeśvara about 16 km; Gokarṇa about 68 km.','<b>Season.</b> October to March is the most comfortable.'],[('z','Three temples in a day?'),('b','Possible, Zappy. Better in two.')],'A coast <b>of shrines</b>.'),
('meaning','A GOD FOR HARD TIMES','What Iḍagunji teaches',stand('A calm standing Gaṇeśa','begin with him'),['<b>For the Kali age.</b> The sages wanted Gaṇeśa’s protection before a hard age began. Many read this as: begin difficult times with prayer. (Interpretation.)','<b>Simple form.</b> Two arms, a sweet and a lotus: a homely god for ordinary people.','<b>A million visitors.</b> Families keep coming, generation after generation, to begin things here.'],[('z','We live in the Kali age now?'),('b','So tradition says, Zappy. Good thing he came.')],'A god for <b>hard times</b>.'),
('rail','GETTING THERE','Road and rail',svg(560,150,'A train on a coastal line and a bus on a road to a temple',f'<rect width="560" height="150" fill="#e3f5e9"/><path d="M0 110 L560 110" stroke="#555" stroke-width="6" stroke-dasharray="14 6"/>'+g(450,95,.8,palace())),['<b>Rail.</b> Manki is the nearest station on the Konkan Railway.','<b>Road.</b> The coastal highway runs close by; Honnāvar is the taluk town.','<b>Practical.</b> Arrangements vary; check locally before you go.'],[('z','By train along the coast?'),('b','A beautiful line, Zappy.')],'On the <b>Konkan line</b>.')],
words=W,gtk=[('z','Tīrtha means pond?'),('b','A sacred pond or crossing-place, Zappy.')],
end=['<b>Where.</b> Iḍagunji, Honnāvar, near the Śarāvatī.','<b>Legend.</b> Sages and Nārada at the end of an age.','<b>Image.</b> Standing, two-armed, modaka and lotus.','<b>Temple.</b> Several tanks; Nārada nearby.','<b>Circuit.</b> With Gokarṇa and Muruḍeśvara.'],endnext='Next: '+L('/ganesha/temples/hampi/','Hampi’s Gaṇeśas')+'.',
src=SRC('Idagunji'),unver='the temple’s age (tradition); visitor numbers (estimates); the tusk reading (devotional).',study='Study notes on Iḍagunji.'))
# ---------- HAMPI ----------
temple(11,dict(kicker='GAṆEŚA TEMPLES · VIJAYANAGARA · TWO MONOLITHS',
cov=covart('Two huge stone Gaṇeśas among boulders, one in an open pavilion',g(140,190,1.6,ganesha(c='#9a9a9a'))+'<rect x="80" y="70" width="120" height="8" fill="#8a7a6a"/>'+g(320,190,2,ganesha(c='#8a8a8a'))+''.join(f'<ellipse cx="{x}" cy="200" rx="30" ry="18" fill="#c9a06a"/>' for x in (30,230,420))),
cap='Mustard-seed and Bengal-gram',how='Two <b>monolithic</b> Gaṇeśas on Hemakūṭa hill: <b>Sāsivekāḷu</b> and <b>Kaḍalekāḷu</b>, the inscription of 1506, the city of <b>Vijayanagara</b>, and walking the ruins.',
desc='Hampi’s two Gaṇeśas explained: Sāsivekāḷu, the mustard-seed Gaṇeśa, and Kaḍalekāḷu, the Bengal-gram Gaṇeśa, monoliths on Hemakūṭa hill; the 1506 inscription; the Vijayanagara capital; and visiting.',
fw=['Among the boulders of <b>Hampi</b>, the ruined capital of the Vijayanagara empire, sit two Gaṇeśas each carved from a single rock. People named them after their bellies: <b>Sāsivekāḷu</b>, “mustard seed”, and <b>Kaḍalekāḷu</b>, “Bengal gram”.','This guide covers both images, the inscription that dates one of them, the city around them, the story of the snake belt, and how to visit.'],fwtk=[('z','Named after his tummy?'),('b','Fondly, Zappy. Hampi’s people have a sense of humour.')],
glance=[('Where','Hemakūṭa hill, Hampi, Vijayanagara district'),('Sāsivekāḷu','About 2.4 m; monolith in an open pavilion'),('Kaḍalekāḷu','About 4.6 m; one of the largest in the south'),('Names','After the shape of their bellies'),('Date','Pavilion of 1506, by an inscription'),('City','Vijayanagara, capital 14th–16th c.'),('Status','Part of a UNESCO World Heritage Site'),('Visit','Free; 30–45 minutes for both')],
where=['<b>Hemakūṭa hill.</b> Both images stand on the slopes of Hemakūṭa, near the Virūpākṣa temple and the Hampi bazaar.','<b>Close together.</b> They are a short walk apart.','<b>Boulders.</b> The granite landscape on the Tuṅgabhadrā gave sculptors stone for monoliths.'],wtk=[('z','Near the Virūpākṣa temple?'),('b','A short walk, Zappy.')],wk='On <b>Hemakūṭa</b>.',
lt='THE SNAKE BELT',ls='Why a snake is tied round his belly',strip=strip('Three panels: Gaṇeśa eating many modakas; falling off his mouse, sweets spilling; the moon laughing and Gaṇeśa tying a snake round his belly',[panel([(ganesha(),.6),(modaka(),.7)],'#fff3cf',150),panel([(mouse(),.8),(modaka(),.6)],'#fde9c8',150),panel([(moon(),.7),(ganesha(),.5)],'#20243a',150)],['a great feast','the fall','the moon laughs']),lsrc='A widely told Gaṇeśa story; see our Stories guide.',
lsteps=['After a great feast of modakas, Gaṇeśa rode home on his mouse at night.','A snake crossed the path; the mouse shied, and Gaṇeśa fell. His belly burst and the sweets rolled out.','He gathered them up and tied the <b>snake</b> round his belly as a belt.','The <b>moon</b> laughed. Gaṇeśa cursed him. Read '+L('/ganesha/stories/moon-curse/','The moon’s curse')+'.','Sāsivekāḷu wears that snake belt in stone.'],ltk=[('z','The moon laughed at him?'),('b','And regretted it, Zappy.')],lk='The <b>snake belt</b>.',
more=[('sasive','SĀSIVEKĀḶU','The mustard-seed Gaṇeśa',svg(560,170,'A seated stone Gaṇeśa in an open pillared pavilion',f'<rect width="560" height="170" fill="#fde9c8"/>'+''.join(f'<rect x="{x}" y="40" width="12" height="120" fill="#9a8a6a"/>' for x in (160,220,330,390))+'<rect x="150" y="30" width="260" height="12" fill="#8a7a6a"/>'+g(280,160,1.3,ganesha(c='#9a9a9a'))),['<b>Size.</b> About 2.4 m (8 ft), carved from a single boulder.','<b>Pavilion.</b> An open hall; an inscription says a merchant from Candragiri built it in 1506 in memory of King Narasiṃha II.','<b>Hands.</b> Right hands: the broken tusk and a goad; upper left: a noose; a snake tied round the belly.'],[('z','Why mustard seed?'),('b','The belly’s shape, Zappy. Small and round, they say.')],'The <b>mustard-seed</b> Gaṇeśa.'),
('kadale','KAḌALEKĀḶU','The Bengal-gram Gaṇeśa',svg(560,170,'A very tall stone Gaṇeśa inside a tall pillared hall',f'<rect width="560" height="170" fill="#e9d6c0"/>'+''.join(f'<rect x="{x}" y="20" width="14" height="140" fill="#9a8a6a"/>' for x in (130,190,360,420))+g(280,165,1.8,ganesha(c='#8a8a8a'))),['<b>Size.</b> About 4.6 m, carved from one boulder.','<b>Hall.</b> Housed in a tall pillared hall in the Vijayanagara style, 15th–16th century.','<b>Among the largest.</b> One of the biggest Gaṇeśa images in South India.'],[('z','4.6 metres!'),('b','Stand beside him and feel small, Zappy.')],'The <b>Bengal-gram</b> giant.'),
('city','VIJAYANAGARA','The city around them',svg(560,170,'Ruined temples and boulders beside a river',f'<rect width="560" height="170" fill="#fde9c8"/>'+''.join(f'<ellipse cx="{x}" cy="{y}" rx="34" ry="22" fill="#c9a06a"/>' for x,y in ((60,140),(140,150),(460,145),(520,130)))+g(280,140,1,palace())+river(560,165)),['<b>Founded.</b> In the 14th century by Harihara and Bukka.','<b>Splendour.</b> One of the richest cities of medieval India, described by Persian and Portuguese travellers.','<b>The fall.</b> Sacked after the battle of Tālikoṭa in 1565.','<b>Today.</b> A UNESCO World Heritage Site on the Tuṅgabhadrā.'],[('z','A whole empire’s capital?'),('b','For two hundred years, Zappy.')],'A capital <b>in ruins</b>.'),
('monolith','CARVED FROM ONE ROCK','How monoliths are made',svg(560,170,'A sculptor carving a Gaṇeśa out of a boulder',f'<rect width="560" height="170" fill="#fff3cf"/><ellipse cx="300" cy="110" rx="110" ry="60" fill="#c9a06a"/>'+g(300,160,1.2,ganesha(c='#9a9a9a'))+g(150,160,1,person('#1d4f8a'))),['<b>Monolith.</b> The whole image is cut from one boulder, often where it lay.','<b>Boulders of Hampi.</b> The landscape itself supplied the stone: carvers turned rocks into gods.','<b>Other monoliths.</b> Hampi’s great Ugra Narasiṃha is another famous example.'],[('z','They carved where the rock sat?'),('b','Often, Zappy. The god was waiting in the stone.')],'The god <b>in the stone</b>.'),
('meaning','WHY THEY MATTER','Gaṇeśa among the ruins',svg(560,150,'A small devotee before a huge stone Gaṇeśa among ruins',f'<rect width="560" height="150" fill="#fde9c8"/>'+g(330,145,1.6,ganesha(c='#8a8a8a'))+g(170,145,1,namaste('#c0392b'))),['<b>Still worshipped.</b> Though the city fell, people still offer flowers and lamps here.','<b>Humour and love.</b> Naming gods after mustard and gram is affection, not disrespect.','<b>Endurance.</b> Kingdoms pass; Gaṇeśa stays. Many find that the lesson of Hampi. (Interpretation.)'],[('z','The kings are gone, Gaṇeśa stays?'),('b','That’s Hampi in one line, Zappy.')],'Kingdoms pass, <b>Gaṇeśa stays</b>.'),
('visit','VISITING','On foot among the boulders',svg(560,150,'A walking path among boulders to two shrines',f'<rect width="560" height="150" fill="#e3f5e9"/><path d="M0 130 q280 -40 560 0" fill="none" stroke="#b08a5a" stroke-width="8" stroke-dasharray="12 8"/>'+g(160,110,.6,palace())+g(400,110,.6,palace())),['<b>Free.</b> Both are open to all; allow 30–45 minutes for the two.','<b>On foot.</b> Walk from the Virūpākṣa temple and the bazaar.','<b>Season.</b> October to February is coolest; Hampi is hot in summer.'],[('z','Walk in the heat?'),('b','Go early, Zappy.')],'Go <b>early</b>.')],
words=W,gtk=[('z','Monolith is a good word!'),('b','One stone, Zappy.')],
end=['<b>Where.</b> Hemakūṭa hill, Hampi.','<b>Sāsivekāḷu.</b> 2.4 m, pavilion of 1506.','<b>Kaḍalekāḷu.</b> 4.6 m, among the largest.','<b>City.</b> Vijayanagara, fell 1565.','<b>Visit.</b> Free, early, on foot.'],endnext='Next: '+L('/ganesha/temples/bengaluru-dodda-ganapati/','Bengaluru’s Doḍḍa Gaṇapati')+'.',
src=SRC('Sasivekalu Ganesha and Kadalekalu Ganesha'),unver='exact heights (sources differ slightly); the dates of Kaḍalekāḷu’s hall.',study='Study notes on Hampi’s Gaṇeśas.'))
# ---------- DOḌḌA GAṆAPATI ----------
temple(12,dict(kicker='GAṆEŚA TEMPLES · BENGALURU · THE BUTTER GAṆEŚA',
cov=covart('A huge Gaṇeśa carved on a boulder, coated in butter, with a Nandi temple nearby',g(200,190,2,ganesha(c='#f4f1ea'))+g(360,190,1.2,nandi())),
cap='Bengaluru’s big Gaṇeśa',how='The <b>18-foot</b> boulder Gaṇeśa, the <b>butter</b> decoration, <b>Kempegowda</b>, the Bull Temple next door and the <b>groundnut fair</b>.',
desc='Bengaluru’s Doḍḍa Gaṇapati explained: the 18-foot monolith on Bull Temple Road, the benne alaṅkāra of 100 kg of butter, Kempegowda and the founding of Bengaluru, the Bull Temple next door, and the Kaḍalekāyi Parishe groundnut fair.',
fw=['On Bull Temple Road in Basavanagudi stands Bengaluru’s best-known Gaṇeśa: <b>Doḍḍa Gaṇapati</b>, “the big Gaṇapati”, carved on a granite boulder about eighteen feet high.','Several times a year he is covered in about a hundred kilos of butter. This guide covers the image, the butter, the city’s founder Kempegowda, the Bull Temple next door and the groundnut fair.'],fwtk=[('z','A hundred kilos of butter?'),('b','Benne alaṅkāra, Zappy. Wait till you see it.')],
glance=[('Where','Bull Temple Road, Basavanagudi, Bengaluru'),('Image','A monolith about 18 ft high, 16 ft wide'),('Names','Doḍḍa Gaṇapati; also Śakti or Satya Gaṇapati'),('Belief','Svayambhū; said to grow on its right side'),('Butter','Benne alaṅkāra: about 100 kg of butter'),('History','Associated with Kempegowda I (16th century)'),('Neighbour','Doḍḍa Basavana Guḍi, the Bull Temple'),('Fair','Kaḍalekāyi Parishe, last Mondays of Kārtika')],
where=['<b>Basavanagudi.</b> One of Bengaluru’s old neighbourhoods, named after the Nandi temple.','<b>Bugle Rock.</b> The temple and the Bull Temple stand beside the rocky park called Bugle Rock.','<b>City centre.</b> Once on the edge of town, now in the heart of the city.'],wtk=[('z','In the middle of the city?'),('b','The city grew round him, Zappy.')],wk='In <b>Basavanagudi</b>.',
lt='THE FOUNDER AND THE STONE',ls='Kempegowda’s Gaṇeśa',strip=strip('Three panels: a chieftain on horseback; finding a boulder with Gaṇeśa’s shape; building a shrine round it',[panel([(person('#8e1f17'),.9)],'#fde9c8',150),panel([(ganesha(c='#9a9a9a'),.6),(person('#8e1f17'),.7)],'#fff3cf',150),panel([(palace(),.6),(ganesha(),.4)],'#e3f5e9',150)],['the founder','the stone','the shrine']),lsrc='Local tradition.',
lsteps=['<b>Kempegowda I</b>, a chieftain under Vijayanagara, founded Bengaluru in the 16th century.','Tradition says he found a boulder bearing Gaṇeśa’s form.','He built a shrine round it, and the boulder became Doḍḍa Gaṇapati.','The neighbouring Bull Temple was built in his time, in 1537.','The stone is believed svayambhū, and local belief says it is still growing on its right side.'],ltk=[('z','A growing stone?'),('b','So people say, Zappy. Measure it in a hundred years.')],lk='The <b>founder’s</b> Gaṇeśa.',
more=[('image','THE IMAGE','A boulder become Gaṇeśa',svg(560,170,'A huge Gaṇeśa relief carved on a granite boulder',f'<rect width="560" height="170" fill="#fff3cf"/><ellipse cx="280" cy="100" rx="150" ry="80" fill="#c9a06a"/>'+g(280,165,1.8,ganesha(c='#f4f1ea'))),['<b>Size.</b> About 18 feet high and 16 feet wide, carved on a granite boulder.','<b>Names.</b> Doḍḍa Gaṇapati, the big one; also Śakti or Satya Gaṇapati.','<b>Look.</b> Usually painted cream with gold details.'],[('z','Bigger than a house!'),('b','Nearly, Zappy.')],'<b>Eighteen feet</b> of Gaṇeśa.'),
('butter','BENNE ALAṄKĀRA','A coat of butter',svg(560,170,'Priests smoothing butter over a huge Gaṇeśa',f'<rect width="560" height="170" fill="#fff8ec"/>'+g(280,165,1.8,ganesha(c='#fff3b0'))+g(120,160,1,person('#c0392b'))+g(440,160,1,person('#c0392b'))),['<b>Benne.</b> Kannada for butter. About 100 kg is smeared over the image and shaped into decoration.','<b>Sponsored.</b> Devotees can sponsor it; it is the highlight of the temple’s festival week.','<b>Next door.</b> The great Nandi of the Bull Temple is buttered too.'],[('z','Doesn’t it melt?'),('b','In the cool of the shrine it holds, Zappy. Then it’s shared.')],'A hundred kilos of <b>butter</b>.'),
('bull','THE BULL TEMPLE','Doḍḍa Basavana Guḍi',svg(560,170,'A giant stone Nandi in a temple',f'<rect width="560" height="170" fill="#e3eaf3"/>'+g(280,160,2,nandi())+g(470,160,.8,palace())),['<b>The Nandi.</b> A huge monolithic Nandi, one of the largest in India, in the temple built in 1537.','<b>The legend.</b> A bull ate the groundnut crops; farmers prayed, and the bull became stone. (Tradition.)','<b>Pair.</b> Gaṇeśa and Nandi, side by side: son and servant of Śiva.'],[('z','A bull that turned to stone?'),('b','After eating the groundnuts, Zappy.')],'Gaṇeśa and <b>Nandi</b>.'),
('parishe','KAḌALEKĀYI PARISHE','The groundnut fair',svg(560,170,'Stalls piled with groundnuts and crowds on a street',f'<rect width="560" height="170" fill="#fde9c8"/>'+''.join(f'<rect x="{x}" y="110" width="70" height="40" fill="#c98a5a"/><ellipse cx="{x+35}" cy="105" rx="34" ry="12" fill="#a07850"/>' for x in (40,160,280,400))+''.join(g(x,165,.4,person('#1d4f8a')) for x in (110,230,350,470))),['<b>When.</b> On the last Mondays of Kārtika, round the Bull Temple.','<b>What.</b> Farmers bring the first groundnuts of the harvest; the street fills with stalls.','<b>Offering.</b> The first groundnuts are offered to Nandi in thanks.'],[('z','A fair of groundnuts?'),('b','Bengaluru’s favourite, Zappy. Bring a bag.')],'The <b>groundnut</b> fair.'),
('meaning','THE CITY’S GAṆEŚA','What Doḍḍa Gaṇapati means',svg(560,150,'A city skyline behind a big Gaṇeśa',f'<rect width="560" height="150" fill="#dfe9f6"/>'+''.join(f'<rect x="{x}" y="{60+(x%3)*10}" width="40" height="{90-(x%3)*10}" fill="#9fb7d6"/>' for x in range(20,560,60))+g(280,145,1.3,ganesha())),['<b>Old and new.</b> A 16th-century shrine in a modern city of millions.','<b>Abundance.</b> Butter and groundnuts: a farming people’s thanks. (Interpretation.)','<b>Beginnings.</b> Bengalureans still begin new homes and jobs with a visit.'],[('z','He’s seen the whole city grow?'),('b','From a village, Zappy.')],'The <b>city’s</b> Gaṇeśa.'),
('visit','VISITING','Basavanagudi on foot',svg(560,150,'A walk between two temples and a rocky park',f'<rect width="560" height="150" fill="#e3f5e9"/>'+g(140,130,.7,palace())+g(420,130,.7,palace())+'<ellipse cx="280" cy="120" rx="60" ry="24" fill="#c9a06a"/>'),['<b>Walk.</b> Gaṇeśa, the Bull Temple and Bugle Rock are within a few minutes of each other.','<b>Busy days.</b> Caturthī, Saṅkaṣṭī and the parishe.','<b>Practical.</b> Timings are set by the temple; check locally.'],[('z','All on foot?'),('b','A lovely morning walk, Zappy.')],'A <b>morning walk</b>.')],
words=W,gtk=[('z','Benne is butter!'),('b','You’ve learnt Kannada, Zappy.')],
end=['<b>Where.</b> Basavanagudi, Bengaluru.','<b>Image.</b> An 18-foot boulder Gaṇeśa.','<b>Offering.</b> Benne alaṅkāra, 100 kg of butter.','<b>History.</b> Kempegowda I.','<b>Fair.</b> Kaḍalekāyi Parishe at the Bull Temple.'],endnext='Next: '+L('/ganesha/temples/ucchi-pillaiyar/','Ucchi Pillaiyār')+' on Tiruchi’s Rock Fort.',
src=SRC('Dodda Ganapathi Temple'),unver='the Kempegowda finding story (tradition); the growing-image belief; butter quantity (approximate).',study='Study notes on Doḍḍa Gaṇapati.'))
